let LatestTime = toscalar(
    observations
    | summarize max(ingested_at)
);
let PreviousTime = toscalar(
    observations
    | where ingested_at < LatestTime
    | summarize max(ingested_at)
);
let CurrentSnapshot =
    observations
    | where ingested_at == LatestTime
    | project
        trakt_show_id,
        ShowTitle = ['title'],
        CurrentRank = ['rank'],
        CurrentWatchers = watcher_count;
let PreviousSnapshot =
    observations
    | where ingested_at == PreviousTime
    | project
        trakt_show_id,
        PreviousRank = ['rank'],
        PreviousWatchers = watcher_count;
CurrentSnapshot
| join kind=leftouter PreviousSnapshot on trakt_show_id
| extend
    WatcherChange = CurrentWatchers - PreviousWatchers,
    RankChange = PreviousRank - CurrentRank
| top 10 by WatcherChange desc
| project ShowTitle, CurrentRank, CurrentWatchers, WatcherChange, RankChange
